window.JPRD = window.JPRD || { lessons: {} };
Object.assign(window.JPRD.lessons, {
 "8.1": {
  resumen: "La admisión es el primer filtro del procedimiento: la Junta revisa que la solicitud cumpla lo mínimo y, si procede, la traslada a la contraparte para que ejerza su defensa. Un buen traslado protege el debido proceso y evita nulidades posteriores.",
  ideas: [
   "La solicitud de disputa se presenta según las reglas del organismo que administra la Junta y el contrato de obra; la Junta verifica forma, competencia y oportunidad antes de avanzar.",
   "Admitir no es dar la razón: es reconocer que el pedido puede tramitarse. El fondo se decide después, con las pruebas de ambas partes.",
   "El traslado debe incluir la solicitud completa y sus anexos, de modo que la contraparte conozca exactamente lo que se le atribuye y lo que se le pide.",
   "Si la Junta detecta omisiones subsanables, suele conceder un plazo breve para corregirlas; conviene atender ese requerimiento con precisión y sin ampliar la pretensión.",
   "La constancia de notificación (fecha, medio y destinatario) es clave: de ella depende el cómputo de los plazos posteriores.",
   "Residente y supervisor deben saber a quién notificar en su organización y revisar a diario el canal designado para notificaciones.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Revisar el reglamento de la Junta y el contrato para confirmar el canal, el formato y los destinatarios de la solicitud.",
   "Comprobar que la solicitud incluya pretensión, hechos, fundamentos y anexos legibles y foliados.",
   "Verificar la competencia: confirmar que la materia sea de las que la Junta puede conocer según el contrato y las reglas aplicables.",
   "Notificar a la contraparte por el medio pactado y conservar el cargo de recepción.",
   "Registrar en un cuadro de control la fecha de notificación y los plazos que se derivan de ella.",
   "Atender de inmediato cualquier requerimiento de subsanación que emita la Junta."
  ],
  errores: [
   "Enviar el traslado a una dirección o persona equivocada: confirmar por escrito los datos de notificación al inicio de la obra.",
   "Presentar anexos incompletos o ilegibles: revisar el juego completo antes de enviar y guardar copia idéntica.",
   "Confundir admisión con pronunciamiento favorable: no comunicar a la entidad o al contratista que ya se ganó algo.",
   "Ignorar el requerimiento de subsanación por creer que es un trámite menor: puede afectar la continuidad del procedimiento."
  ],
  ejemplo: "Un contratista presenta una solicitud por una ampliación de plazo denegada en una obra de saneamiento (monto ilustrativo: S/ 4,8 millones). La Junta advierte que faltan dos anexos citados en el texto y otorga un plazo breve de subsanación. El contratista completa los anexos sin modificar su pedido y la Junta traslada la solicitud a la entidad, dejando constancia de la fecha de notificación. La entidad, al recibirla, registra el inicio de sus plazos de respuesta según el reglamento aplicable. Cifras y plazos son ilustrativos.",
  practica: "Toma un contrato de obra real o ficticio y arma una lista de control de admisión con cinco verificaciones (competencia, forma, anexos, destinatario, cargo de notificación). Aplícala a una solicitud imaginaria e identifica qué omisión sería subsanable.",
  quiz: [
   {q:"¿Qué significa que la Junta admita una solicitud?", o:["Que acepta la pretensión del solicitante","Que la solicitud puede tramitarse y pasa a la contraparte","Que la disputa ya fue resuelta","Que se suspende la obra"], ok:1, why:"La admisión es un filtro de forma y competencia; el fondo se resuelve después de oír a ambas partes."},
   {q:"¿Por qué es importante el cargo de notificación?", o:["Porque reemplaza a la contestación","Porque fija el monto de la disputa","Porque decide la competencia","Porque de la fecha de notificación se computan los plazos siguientes"], ok:3, why:"Sin constancia clara de fecha y medio, los plazos posteriores pueden discutirse."}
  ]
 },
 "8.2": {
  resumen: "La contestación es la oportunidad de la parte demandada para exponer su versión, sus pruebas y sus límites. Una respuesta ordenada, que separe hechos, contrato y prueba, suele ser más útil para la Junta que una respuesta extensa pero dispersa.",
  ideas: [
   "La contestación se presenta dentro del plazo fijado por el reglamento de la Junta y el contrato; su vencimiento debe verificarse desde el día de la notificación.",
   "Responder punto por punto a la pretensión evita que queden hechos sin controvertir, que la Junta podría considerar como no discutidos.",
   "Conviene distinguir los hechos que se aceptan, los que se niegan y los que se precisan con contexto, sin negar por reflejo lo que consta en el cuaderno de obra.",
   "La estrategia debe partir del contrato de obra: qué obligaba a cada parte, qué comunicaciones se cursaron y en qué momento.",
   "Las excepciones o cuestionamientos de competencia y oportunidad se plantean en la contestación, cuando corresponda según las reglas aplicables.",
   "Cada afirmación relevante debe tener respaldo: asiento de cuaderno, carta, acta, metrado, informe o registro fotográfico.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Leer la solicitud completa y extraer una lista de hechos alegados y pedidos concretos.",
   "Contrastar cada hecho con el cuaderno de obra, las cartas y las actas para clasificarlo como cierto, falso o incompleto.",
   "Definir la línea central de defensa en una o dos frases, alineada con el contrato.",
   "Redactar la contestación siguiendo el orden de la solicitud, con anexos numerados.",
   "Revisar que no se contradigan escritos anteriores de la propia parte.",
   "Presentar dentro del plazo y guardar el cargo de recepción."
  ],
  errores: [
   "Contestar en términos generales sin responder cada pretensión: usar una tabla de pretensión y respuesta.",
   "Negar hechos que constan en documentos propios: revisar antes el cuaderno de obra y las comunicaciones.",
   "Dejar para la audiencia pruebas que debieron ofrecerse con la contestación: consultar las reglas sobre oportunidad de la prueba.",
   "Usar un tono agresivo hacia la contraparte o la Junta: privilegiar hechos, contrato y prueba."
  ],
  ejemplo: "En una obra vial (monto ilustrativo: S/ 12 millones), el contratista reclama mayores gastos generales por una paralización que atribuye a la entidad. La entidad, al contestar, acepta que hubo una paralización, pero sostiene que parte de ese periodo se debió a la falta de personal del contratista, citando asientos del cuaderno de obra del supervisor. Precisa además que la comunicación formal del contratista se cursó tarde según el contrato. Presenta los asientos y cartas como anexos numerados. No se afirma resultado alguno; la Junta valorará ambas posiciones.",
  practica: "Con una solicitud ficticia de tres pretensiones, elabora un cuadro de dos columnas (pretensión / respuesta con prueba de respaldo). Marca qué respuestas dependen de verificar el contrato.",
  quiz: [
   {q:"¿Qué ventaja tiene responder punto por punto la solicitud?", o:["Evita que queden hechos sin controvertir","Permite omitir las pruebas","Alarga el plazo del procedimiento","Sustituye la audiencia"], ok:0, why:"Los hechos no respondidos pueden entenderse como no discutidos, lo que debilita la defensa."},
   {q:"¿Cuál es una buena base para construir la estrategia de contestación?", o:["La reputación de la contraparte","El contrato de obra y los documentos de respaldo","La cantidad de páginas del escrito","Las expectativas del área comercial"], ok:1, why:"El contrato y la prueba documental fijan lo exigible a cada parte y sostienen cada afirmación."}
  ]
 },
 "8.3": {
  resumen: "La audiencia es el espacio donde la Junta escucha a las partes, aclara puntos técnicos y ordena la prueba. Prepararla con guion, roles y documentos a la mano permite aprovechar un tiempo que suele ser limitado.",
  ideas: [
   "La Junta define la forma de la audiencia de acuerdo con sus reglas y el contrato; puede ser presencial, en obra o virtual. Confirmar convocatoria, hora y participantes con anticipación.",
   "Cada parte debe decidir quién habla de qué: el residente o el supervisor para hechos de obra, el especialista para metrados y cronograma, el abogado para el marco contractual.",
   "Un guion breve con tres o cuatro mensajes centrales evita divagar; los detalles se sustentan con anexos ya presentados.",
   "Las preguntas de la Junta son una oportunidad para aclarar, no un ataque; responder con precisión y reconocer lo que no se sabe es mejor que improvisar.",
   "Los documentos clave (cuaderno de obra, cronograma vigente, valorizaciones, planos) deben estar ordenados y ubicables en segundos.",
   "Se debe levantar acta o registro de lo tratado; revisar que refleje fielmente los acuerdos y las precisiones sobre la prueba.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Confirmar convocatoria, modalidad, agenda y reglas de intervención con la Junta.",
   "Designar voceros y asignar temas a cada uno según su especialidad.",
   "Preparar un guion de mensajes centrales y una carpeta de consulta rápida.",
   "Ensayar las respuestas a las preguntas técnicas más probables, incluyendo las que favorecen a la contraparte.",
   "Durante la audiencia, tomar nota de compromisos, pedidos de información y plazos otorgados.",
   "Revisar el acta o registro posterior y observar por escrito cualquier inexactitud."
  ],
  errores: [
   "Llegar sin haber unificado la versión interna: reunirse antes y resolver discrepancias entre residente, especialista y asesor.",
   "Leer extensos escritos en lugar de exponer: sintetizar y remitir a los anexos.",
   "Interrumpir a la contraparte o a la Junta: pedir la palabra y respetar los turnos.",
   "No registrar los compromisos asumidos: designar a una persona que tome nota."
  ],
  ejemplo: "En una audiencia sobre una ampliación de plazo en un colegio (monto ilustrativo: S/ 6,5 millones), la Junta convoca a ambas partes a una sesión de dos horas. El contratista lleva al residente para explicar la secuencia de trabajos y a un planificador para mostrar el cronograma vigente. La entidad lleva al supervisor. La Junta pide precisar qué partida estaba en ruta crítica; el planificador responde con el cronograma actualizado y se compromete a entregar la versión editable dentro del plazo que fije la Junta. Cifras y plazos son ilustrativos.",
  practica: "Prepara un guion de cinco minutos para exponer una disputa ficticia sobre valorizaciones: tres mensajes centrales, documentos de respaldo y dos preguntas difíciles que anticipas.",
  quiz: [
   {q:"¿Qué conviene hacer cuando la Junta formula una pregunta técnica que no se domina?", o:["Improvisar una respuesta firme","Cambiar de tema","Aclarar lo que se sabe, reconocer lo que no y ofrecer completar por escrito","Negarse a responder"], ok:2, why:"La precisión y la honestidad son más útiles que una respuesta improvisada que luego pueda contradecirse."},
   {q:"¿Para qué sirve el guion de mensajes centrales?", o:["Para reemplazar los anexos","Para mantener foco y no divagar","Para extender el tiempo de la audiencia","Para evitar las preguntas de la Junta"], ok:1, why:"Ordena la exposición y deja el detalle a los anexos ya presentados."}
  ]
 },
 "8.4": {
  resumen: "La visita técnica permite a la Junta ver por sí misma el estado de la obra, contrastar lo alegado con lo construido y comprender el contexto físico de la controversia. Requiere coordinación, seguridad y un registro claro de lo observado.",
  ideas: [
   "La Junta puede disponer una inspección de obra cuando el reglamento o el contrato lo permiten; conviene verificar quién la convoca, con qué aviso y quién asiste.",
   "El objetivo no es rehacer la supervisión, sino observar puntos concretos vinculados a la disputa: frentes de trabajo, interferencias, calidad de partidas o accesos.",
   "Ambas partes deben tener oportunidad de asistir y de señalar lo que consideren relevante, para preservar el debido proceso.",
   "La seguridad manda: equipo de protección, inducción y acompañamiento del residente o del personal designado son condiciones previas al ingreso.",
   "El registro de la visita (acta, fotografías fechadas, croquis, mediciones) se incorpora al expediente y debe ser aceptado o al menos conocido por ambas partes.",
   "Es útil preparar un recorrido con estaciones numeradas que coincidan con los anexos de las partes, para que la Junta relacione lo visto con la prueba.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Coordinar fecha, hora, ruta y participantes con la Junta y con la contraparte.",
   "Preparar una lista de puntos a mostrar, con referencia a planos, metrados y anexos.",
   "Asegurar equipos de seguridad, accesos y personal de apoyo para el recorrido.",
   "Acompañar a la Junta siguiendo la ruta acordada, sin adelantar juicios sobre el fondo.",
   "Tomar registro fotográfico y de mediciones que coincida con el de la contraparte, si se acuerda.",
   "Firmar el acta de la visita solo tras revisarla y dejar constancia de discrepancias."
  ],
  errores: [
   "Improvisar el recorrido: elaborar una ruta y un orden lógico antes de la visita.",
   "Modificar el estado de la obra antes de la inspección para mejorar la impresión: puede afectar la credibilidad y las consecuencias contractuales; documentar el estado real.",
   "Conversar con la Junta sin la contraparte presente: mantener la comunicación abierta a ambos.",
   "No dejar constancia por escrito de lo observado: siempre levantar acta."
  ],
  ejemplo: "Una disputa gira en torno a interferencias con una red de agua en una obra de pavimentación (monto ilustrativo: S/ 9 millones). La Junta programa una visita técnica. El residente propone tres estaciones: el punto de la tubería, el frente afectado y el acceso al almacén. El supervisor acompaña por la entidad. Se toman fotos fechadas, una medición de la profundidad de la tubería y un croquis. El acta registra lo observado y la posición de cada parte sobre su significado, sin resolver aún la controversia. Cifras ilustrativas.",
  practica: "Diseña una ruta de visita con cuatro estaciones para una disputa sobre calidad de concreto en cimentación. Indica qué documento del expediente respalda cada estación y qué riesgos de seguridad debes prever.",
  quiz: [
   {q:"¿Cuál es el propósito principal de una visita técnica de la Junta?", o:["Reemplazar al supervisor","Sancionar al contratista","Aprobar valorizaciones","Contrastar lo alegado con la realidad física de la obra"], ok:3, why:"La Junta busca comprender el contexto físico y verificar puntos concretos de la controversia."},
   {q:"¿Qué se recomienda respecto del estado de la obra antes de la inspección?", o:["Dejarlo tal cual y documentarlo","Ordenarlo para causar buena impresión","Retirar los materiales en discusión","Suspender el trabajo un mes"], ok:0, why:"Alterar el estado real puede restar credibilidad; lo prudente es documentar lo existente."}
  ]
 },
 "8.5": {
  resumen: "Los informes de peritos y la prueba técnica ayudan a la Junta a comprender cuestiones especializadas como metrados, cronogramas, calidad de materiales o costos. Su valor depende de la claridad del método, la independencia y la trazabilidad de los datos.",
  ideas: [
   "El peritaje puede ser de parte o solicitado por la Junta, según las reglas aplicables; conviene verificar en el reglamento cómo se ofrece, se admite y se contradice.",
   "Un buen informe declara su objeto, los documentos revisados, el método, los cálculos y las conclusiones, de forma que un tercero pueda reproducirlo.",
   "La independencia del perito no se presume: revelar cualquier vínculo con las partes fortalece la confianza en su opinión.",
   "El perito no reemplaza a la Junta: aporta análisis técnico, pero la valoración final de la prueba corresponde a quien decide.",
   "Los informes de laboratorio y ensayos deben mostrar cadena de custodia, fecha, norma técnica aplicada y laboratorio acreditado, cuando corresponda.",
   "La contraparte puede observar el informe o pedir aclaraciones; anticipar esas preguntas mejora la calidad del trabajo pericial.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Definir con precisión la pregunta técnica que el peritaje debe responder.",
   "Reunir y entregar al perito los documentos relevantes: expediente técnico, cronogramas, metrados y registros.",
   "Solicitar que el informe explique método, supuestos y limitaciones.",
   "Revisar que las conclusiones se deriven de los datos y no excedan el alcance encargado.",
   "Presentar el informe con anexos ordenados y dentro de la oportunidad prevista.",
   "Preparar al perito para responder preguntas en audiencia."
  ],
  errores: [
   "Encargar un informe sin delimitar la pregunta: el resultado suele ser extenso y poco útil.",
   "Ocultar datos desfavorables al perito: la contraparte puede detectarlos y restar credibilidad.",
   "Presentar conclusiones sin respaldo de cálculos: adjuntar hojas de cálculo y fuentes.",
   "Usar ensayos sin trazabilidad: verificar laboratorio, fechas y normas técnicas."
  ],
  ejemplo: "En una obra de edificación (monto ilustrativo: S/ 15 millones), se discute si un retraso se debió a modificaciones de diseño. El contratista presenta un informe de un planificador que reconstruye el cronograma con y sin los cambios, explicando el método y las hojas de cálculo. La entidad observa que el informe no incluyó un periodo de lluvias y solicita una aclaración. La Junta decide pedir a ambas partes que las diferencias metodológicas se expliquen en audiencia. No se anticipa qué criterio prevalecerá. Datos ilustrativos.",
  practica: "Redacta el encargo a un perito para una controversia sobre metrados de movimiento de tierras: objeto, documentos a entregar, método esperado y tres preguntas que la contraparte podría formular.",
  quiz: [
   {q:"¿Qué debe permitir un buen informe pericial?", o:["Ocultar el método para proteger al perito","Que un tercero comprenda y reproduzca el análisis","Reemplazar la decisión de la Junta","Evitar la contradicción de la contraparte"], ok:1, why:"La trazabilidad y claridad del método dan solidez a la prueba técnica."},
   {q:"¿Quién valora finalmente la prueba pericial?", o:["El perito","La entidad","La Junta","El contratista"], ok:2, why:"El perito aporta análisis; la valoración conjunta de la prueba corresponde a quien decide."}
  ]
 },
 "8.6": {
  resumen: "Los plazos ordenan el procedimiento y determinan qué actos son oportunos. Saber cómo se cuentan, desde cuándo y con qué excepciones evita perder derechos por una mala lectura del calendario.",
  ideas: [
   "Los plazos del procedimiento provienen del reglamento de la Junta, del contrato de obra y de las normas aplicables; no deben asumirse de memoria sino verificarse en cada caso.",
   "Hay que identificar el hecho que inicia el cómputo (notificación, recepción, fecha de un acto) y si los plazos se cuentan en días calendario o hábiles según lo establecido.",
   "Un calendario del procedimiento, alimentado apenas llega cada notificación, es la herramienta más simple para evitar vencimientos.",
   "Los plazos suelen ser distintos para presentar, contestar, subsanar y cumplir; mezclarlos genera errores.",
   "Las solicitudes de prórroga o de reprogramación deben pedirse antes del vencimiento y con fundamentos, sin dar por hecho que serán concedidas.",
   "Conviene guardar evidencia de fecha y hora de cada presentación, incluso en canales electrónicos.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Identificar en el reglamento y el contrato cada plazo aplicable y su unidad de cómputo.",
   "Registrar en un calendario compartido la fecha de inicio y de vencimiento de cada acto.",
   "Configurar alertas internas con margen antes de cada vencimiento.",
   "Asignar un responsable por cada acto y un suplente.",
   "Presentar los escritos con holgura y guardar el cargo.",
   "Solicitar por escrito la prórroga o aclaración con anticipación si hay razones justificadas."
  ],
  errores: [
   "Contar plazos desde una fecha equivocada: partir siempre del cargo de notificación.",
   "Confundir días hábiles con calendario: revisar la definición aplicable.",
   "Presentar el último día sin margen ante fallas técnicas: adelantar la presentación.",
   "Asumir que una prórroga será aceptada: mantener el plazo original como referencia hasta que la Junta resuelva."
  ],
  ejemplo: "Una entidad recibe el traslado de una solicitud un jueves por la tarde. El asesor registra la fecha del cargo, identifica que el reglamento y el contrato fijan un plazo de contestación y verifica si se cuentan días hábiles. Arma un calendario con tres hitos internos: borrador, revisión técnica y presentación, esta última con dos días de margen. Como un anexo depende de un informe del supervisor, solicita a este entregarlo con anticipación. Los plazos concretos mencionados en la práctica deben confirmarse en la norma aplicable; este caso es ilustrativo.",
  practica: "Construye un calendario de procedimiento para una disputa ficticia con cinco actos (admisión, contestación, audiencia, informe pericial, decisión). Indica para cada uno la fuente del plazo que debes verificar.",
  quiz: [
   {q:"¿Desde cuándo debe empezar a contarse normalmente un plazo de respuesta?", o:["Desde la firma del contrato","Desde el inicio de la obra","Desde la audiencia","Desde el hecho que lo activa, como la notificación, según la norma aplicable"], ok:3, why:"El punto de partida lo fija la norma; comúnmente es la notificación, por eso el cargo es clave."},
   {q:"¿Qué conviene hacer si se necesita más tiempo para un acto?", o:["Esperar a que venza el plazo","Solicitar la prórroga fundamentada antes del vencimiento","Presentar sin anexos","Asumir que se concederá"], ok:1, why:"La solicitud debe hacerse a tiempo y sin dar por hecho su aprobación."}
  ]
 },
 "9.1": {
  resumen: "Una decisión bien estructurada identifica las cuestiones controvertidas, expone los hechos probados, aplica el contrato y la norma, y concluye con un mandato claro. La motivación es lo que permite a las partes comprender y, si corresponde, cumplir o cuestionar lo decidido.",
  ideas: [
   "Las reglas de la Junta y el contrato indican los contenidos mínimos de la decisión; conviene revisarlos para saber qué esperar y qué exigir.",
   "Una estructura habitual incluye antecedentes, posiciones de las partes, cuestiones a resolver, análisis y parte resolutiva; el orden puede variar según las reglas.",
   "Motivar significa explicar por qué se llega a cada conclusión: qué hecho se consideró probado, qué cláusula contractual se aplicó y qué prueba fue determinante.",
   "Una parte resolutiva clara indica qué se ordena, quién debe hacerlo y en qué plazo, para reducir discusiones de interpretación al cumplir.",
   "Las partes que aportan prueba ordenada y pretensiones precisas facilitan una decisión mejor fundada.",
   "Leer la decisión completa, no solo el resumen, es indispensable para el residente, el supervisor y el asesor legal que deben ejecutarla.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Ubicar en el reglamento y el contrato qué debe contener la decisión.",
   "Al recibirla, leer los antecedentes y confirmar que reflejan fielmente las pretensiones.",
   "Identificar cada cuestión resuelta y su fundamento.",
   "Extraer de la parte resolutiva una lista de obligaciones, responsables y plazos.",
   "Comparar las conclusiones con las pruebas ofrecidas para detectar omisiones.",
   "Si el reglamento lo permite, evaluar solicitudes de aclaración o corrección dentro del plazo previsto."
  ],
  errores: [
   "Quedarse solo con el resumen: leer el análisis completo para entender los límites de lo decidido.",
   "Interpretar la parte resolutiva a conveniencia: pedir aclaración cuando el texto no sea claro.",
   "No advertir que un punto quedó sin resolver: contrastar las pretensiones con la decisión.",
   "Pedir aclaraciones fuera de plazo: verificar cuándo y cómo el reglamento las admite."
  ],
  ejemplo: "Una Junta resuelve una disputa sobre un adicional de obra (monto ilustrativo: S/ 850 mil). La decisión identifica dos cuestiones: si el trabajo estaba previsto en el expediente técnico y cuál era su valor. Sobre la primera, analiza planos, metrados y asientos del cuaderno de obra; sobre la segunda, evalúa los precios unitarios presentados. La parte resolutiva indica qué pedido se acoge parcialmente y cuál se rechaza, y qué debe hacer cada parte. Las partes revisan si algún punto es ambiguo. Los montos y conclusiones son ilustrativos y no anticipan casos reales.",
  practica: "Toma una decisión ficticia de una página y subraya: cuestiones resueltas, hechos probados, fundamento contractual y mandato. Indica una frase de la parte resolutiva que pedirías aclarar.",
  quiz: [
   {q:"¿Qué significa motivar una decisión?", o:["Explicar por qué se llega a cada conclusión con hechos, prueba y contrato","Resumir la posición de una parte","Adjuntar todos los anexos","Repetir la solicitud"], ok:0, why:"La motivación permite comprender el razonamiento y ejecutar o cuestionar la decisión."},
   {q:"¿Por qué es útil una parte resolutiva clara?", o:["Porque evita revisar el análisis","Porque asegura ganar el caso","Porque reduce discusiones de interpretación al cumplir","Porque elimina plazos"], ok:2, why:"Precisar qué, quién y cuándo facilita el cumplimiento y evita nuevas controversias."}
  ]
 },
 "9.2": {
  resumen: "El carácter vinculante de la decisión determina qué deben hacer las partes mientras dura la obra. Su alcance, su duración y sus posibilidades de revisión dependen del contrato, de las reglas de la Junta y de la normativa aplicable, que deben verificarse en cada caso.",
  ideas: [
   "En los sistemas de Junta, la decisión suele obligar a las partes durante la ejecución, aunque pueda revisarse después en otra vía; el detalle exacto depende de la norma vigente y del contrato.",
   "Ser vinculante no equivale a ser definitiva en todos los casos: existen mecanismos posteriores de revisión, como la conciliación o el arbitraje, según lo previsto.",
   "Las partes deben conocer desde el inicio de la obra cuál es el efecto de una decisión: obligación inmediata, plazo para cumplir o para cuestionarla.",
   "El residente y el supervisor deben recibir instrucciones internas claras: cumplir lo decidido no significa renunciar a la revisión posterior si está prevista.",
   "Las decisiones vinculantes ordenan la ejecución; ignorarlas puede generar consecuencias contractuales que conviene revisar con asesoría.",
   "Antes de impugnar, evaluar costo, plazo y probabilidad razonable de cambio, sin asumir resultados.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Revisar en el contrato y el reglamento el efecto de la decisión y sus plazos de cumplimiento.",
   "Comunicar internamente lo decidido al equipo de obra y a las áreas que intervienen.",
   "Determinar si existe un plazo para cuestionarla y qué vía corresponde.",
   "Registrar por escrito la reserva de derechos, si el contrato y la norma lo permiten.",
   "Ejecutar lo ordenado dentro del plazo, con registro en el cuaderno de obra.",
   "Documentar los costos y efectos del cumplimiento para futuras discusiones."
  ],
  errores: [
   "Creer que vinculante significa inapelable: verificar las vías de revisión previstas.",
   "Dejar de cumplir esperando la revisión: salvo que la norma lo autorice, la obligación puede seguir vigente.",
   "No comunicar la decisión al equipo de obra: coordinar internamente antes de que venzan los plazos.",
   "No registrar la reserva de derechos: si el contrato la contempla, formularla oportunamente."
  ],
  ejemplo: "La Junta ordena a la entidad reconocer un costo adicional por una paralización (monto ilustrativo: S/ 320 mil). La entidad estima que la decisión es discutible y evalúa su revisión posterior, pero también advierte que la decisión obliga mientras dure la obra. Coordina con su área legal para cumplir en el plazo indicado, dejando constancia de que se reserva el derecho de cuestionarla en la vía prevista. El contratista registra el pago. Nada de esto asegura un resultado en la revisión posterior. Datos ilustrativos.",
  practica: "Redacta un memorando interno de media página para el equipo de obra explicando qué implica una decisión vinculante y qué acciones deben tomar en las primeras 48 horas, dejando claro qué se debe verificar en el contrato.",
  quiz: [
   {q:"¿Vinculante significa siempre definitiva?", o:["Sí, no admite revisión","Solo si la ganó el contratista","No necesariamente: puede haber vías de revisión posteriores según la norma y el contrato","Solo si la firma el supervisor"], ok:2, why:"El efecto obligatorio durante la ejecución coexiste con posibles revisiones posteriores, que deben verificarse."},
   {q:"¿Qué hacer si una parte discrepa de lo decidido?", o:["Ignorar la decisión","Evaluar la vía de revisión prevista y cumplir mientras tanto lo que corresponda","Paralizar la obra","Modificar el cuaderno de obra"], ok:1, why:"La discrepancia se canaliza por las vías previstas; la obligación sigue vigente salvo disposición contraria."}
  ]
 },
 "9.3": {
  resumen: "Cumplir una decisión en obra exige traducirla en actividades concretas: quién hace qué, con qué recursos y en qué plazo. Los equipos que planifican el cumplimiento reducen fricciones y dejan registro para eventuales revisiones.",
  ideas: [
   "La decisión debe convertirse en un plan de acción con responsables, hitos y evidencias, y no quedar como un documento archivado.",
   "El residente coordina lo operativo, el supervisor verifica y la entidad realiza los actos administrativos que corresponda; cada rol debe estar claro.",
   "El cuaderno de obra debe reflejar los actos de cumplimiento: instrucciones, inicio de trabajos, recepción de materiales o suspensión de una actividad.",
   "Si el cumplimiento depende de trámites internos, como una modificación presupuestal o una aprobación, hay que iniciar esos trámites de inmediato.",
   "Cuando la decisión sea ambigua, conviene pedir aclaración por escrito y no ejecutar por interpretación propia.",
   "El registro de costos y plazos asociados al cumplimiento sirve como sustento en futuras discusiones.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Extraer de la decisión cada obligación con su responsable y plazo.",
   "Elaborar un plan de cumplimiento con hitos semanales y evidencias esperadas.",
   "Comunicar las instrucciones a los frentes de obra y anotar en el cuaderno.",
   "Iniciar los trámites administrativos y presupuestales que se requieran.",
   "Verificar el avance con el supervisor y registrar fotos, actas y documentos.",
   "Informar a la Junta y a la contraparte del cumplimiento, cuando corresponda."
  ],
  errores: [
   "Cumplir parcialmente sin informar: comunicar avances y dejar constancia.",
   "No registrar lo hecho: anotar cada acto en el cuaderno de obra.",
   "Ejecutar una interpretación propia de un punto ambiguo: solicitar aclaración a tiempo.",
   "Descuidar trámites internos que demoran: iniciarlos desde el primer día."
  ],
  ejemplo: "La Junta ordena reprogramar una actividad y reconocer un costo asociado en una obra de agua potable (monto ilustrativo: S/ 480 mil). El residente elabora un plan con tres hitos: nueva secuencia constructiva, adquisición de materiales y cierre de valorización. El supervisor verifica cada hito y anota en el cuaderno. La entidad inicia el trámite administrativo del pago. Todo se documenta con actas y fotografías. Las cifras son ilustrativas.",
  practica: "Con una decisión ficticia que ordena dos acciones (reprogramar y pagar), elabora un plan de cumplimiento en una tabla con obligación, responsable, plazo y evidencia.",
  quiz: [
   {q:"¿Qué debe hacerse ante una orden ambigua de la decisión?", o:["Ejecutar según convenga","Pedir aclaración por escrito dentro del plazo aplicable","Ignorarla","Esperar a que la contraparte actúe"], ok:1, why:"La aclaración evita cumplir mal y conflictos posteriores."},
   {q:"¿Dónde debe quedar reflejado el cumplimiento operativo?", o:["Solo en un correo interno","Solo en la memoria anual","En una nota informal","En el cuaderno de obra y en actas y registros"], ok:3, why:"El cuaderno de obra y los registros dan trazabilidad y prueba del cumplimiento."}
  ]
 },
 "9.4": {
  resumen: "Una decisión de la Junta puede afectar pagos, valorizaciones y el cronograma. Comprender cómo se reflejan esos efectos evita desfases entre lo ordenado y lo ejecutado, y facilita la coordinación entre entidad, contratista y supervisión.",
  ideas: [
   "Si la decisión reconoce un monto, se debe definir cómo se paga: en una valorización, mediante un trámite separado o según lo que establezcan el contrato y las normas aplicables.",
   "Si reconoce una ampliación de plazo, se debe actualizar el cronograma vigente y verificar el impacto en la ruta crítica y en los calendarios de adquisiciones y de avance.",
   "Los efectos sobre el pago dependen de la naturaleza de lo reconocido: costo directo, gastos generales, reajustes o intereses; no todos siguen el mismo trámite.",
   "El supervisor y la entidad deben coordinar la aprobación de documentos que sustenten el pago, evitando trabas administrativas.",
   "El contratista debe reflejar los efectos en su programación, su flujo de caja y sus garantías, si aplica.",
   "Registrar en el cuaderno de obra las modificaciones del cronograma y del calendario de valorizaciones.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Identificar en la decisión qué conceptos económicos y qué ajustes de plazo reconoce.",
   "Determinar con el contrato y las normas el trámite de pago aplicable.",
   "Actualizar el cronograma y el calendario de valorizaciones, y recalcular la ruta crítica.",
   "Emitir o aprobar los documentos de sustento con la supervisión.",
   "Comunicar a las áreas financieras y de presupuesto para programar el pago.",
   "Verificar la consistencia entre lo decidido, lo pagado y lo programado."
  ],
  errores: [
   "Pagar sin sustento documental: preparar el expediente de pago con la decisión y la conformidad.",
   "No actualizar el cronograma: el plazo reconocido debe reflejarse formalmente.",
   "Olvidar el efecto sobre garantías o reajustes: revisar contrato y normas aplicables.",
   "Mezclar conceptos en una sola línea de pago: separarlos según su naturaleza."
  ],
  ejemplo: "Una decisión reconoce siete días de ampliación de plazo y un pago por mayores gastos generales en una obra de mejoramiento vial (monto ilustrativo: S/ 210 mil). El supervisor actualiza el cronograma, evalúa el impacto en la ruta crítica y la entidad tramita el pago según el procedimiento aplicable. El contratista ajusta su programación y anota en el cuaderno los cambios. Los días y montos son ilustrativos; cada caso depende de lo que decida la Junta y de lo que fije el contrato.",
  practica: "Dada una decisión ficticia que reconoce un monto y un plazo, dibuja un flujo de cinco pasos que muestre cómo se refleja en valorización y cronograma, indicando qué documento respalda cada paso.",
  quiz: [
   {q:"Si la decisión reconoce una ampliación de plazo, ¿qué debe actualizarse?", o:["Solo el nombre de la obra","El cronograma vigente y sus calendarios asociados","El plano de ubicación","La tarifa del supervisor"], ok:1, why:"El plazo reconocido debe reflejarse en el cronograma y los calendarios."},
   {q:"¿Por qué conviene separar conceptos económicos al pagar?", o:["Para disimular montos","Porque todos siguen el mismo trámite","Para retrasar el pago","Porque pueden tener naturaleza y trámite distintos"], ok:3, why:"Costo directo, gastos generales o reajustes pueden tener tratamientos diferentes."}
  ]
 },
 "9.5": {
  resumen: "Las decisiones de la Junta pueden ser revisadas después en otras vías, como la conciliación o el arbitraje, según lo previsto en el contrato y en la normativa. Evaluar esa opción exige mirar plazos, costos, prueba disponible y estrategia.",
  ideas: [
   "Las vías de revisión y sus plazos dependen de la Ley de Contrataciones Públicas y su Reglamento vigentes, de las directivas aplicables y del contrato de obra; deben verificarse antes de decidir.",
   "La conciliación busca un acuerdo con ayuda de un tercero; el arbitraje conduce a un laudo. Cada vía tiene lógica, costos y tiempos diferentes.",
   "Antes de acudir a otra vía, conviene revisar si la decisión de la Junta ya cumplió su función práctica: desbloquear la obra y ordenar la ejecución.",
   "El expediente y la prueba generados ante la Junta son un insumo valioso para la revisión posterior; por eso conviene mantenerlos ordenados.",
   "Iniciar una revisión no siempre suspende el cumplimiento de la decisión; hay que verificar el efecto en la norma y el contrato.",
   "Evaluar la conveniencia con criterios objetivos: montos en juego, calidad de la prueba, relación futura y riesgo de demora.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Revisar el contrato y la normativa para identificar vías, plazos y requisitos de revisión.",
   "Analizar la decisión y clasificar los puntos favorables y desfavorables.",
   "Estimar costos, tiempos y riesgos de cada vía sin asumir un resultado.",
   "Evaluar una negociación previa o una conciliación como alternativa.",
   "Decidir con el área legal y la dirección de la obra, y documentar la decisión.",
   "Si se opta por la revisión, preparar el expediente con la decisión, la prueba y la cronología."
  ],
  errores: [
   "Dejar vencer el plazo para cuestionar: registrar la fecha límite en el calendario.",
   "Asumir que la revisión cambiará el resultado: evaluar riesgos con prudencia.",
   "No mantener ordenado el expediente: conservar toda la prueba presentada.",
   "Confundir cumplimiento con renuncia: cumplir no impide revisar si la norma lo permite."
  ],
  ejemplo: "Un contratista recibe una decisión parcialmente desfavorable sobre mayores gastos generales (monto ilustrativo: S/ 600 mil). Antes de decidir, revisa el contrato, calcula el costo y el tiempo de un arbitraje, y evalúa la conciliación. Concluye que, dada la solidez de parte de su prueba y el monto, conviene explorar primero una conciliación. Conserva el expediente completo y registra los plazos. Nada asegura que la vía elegida modifique lo decidido. Cifras ilustrativas y sujetas a verificación normativa.",
  practica: "Elabora una matriz con dos columnas (conciliación y arbitraje) y filas de plazo, costo, prueba y relación futura, para una decisión ficticia. Marca qué datos debes verificar en el contrato.",
  quiz: [
   {q:"¿Qué debe verificarse antes de acudir a una vía de revisión?", o:["La opinión del proveedor","Solo el monto de la obra","Contrato, normativa vigente, plazos y requisitos","El color del cuaderno"], ok:2, why:"Las vías y sus plazos dependen de la norma vigente y del contrato."},
   {q:"¿Cuál es un insumo valioso para la revisión posterior?", o:["El expediente y la prueba producidos ante la Junta","Rumores","Comentarios informales","Ninguno"], ok:0, why:"Lo presentado ante la Junta puede servir de base en la vía posterior."}
  ]
 },
 "9.6": {
  resumen: "Cuando una parte no cumple una decisión, la otra debe actuar con orden: documentar el incumplimiento, comunicarlo formalmente y evaluar las vías previstas en el contrato y la norma. Reaccionar de forma impulsiva puede perjudicar la posición propia.",
  ideas: [
   "El primer paso es comprobar qué se ordenó, en qué plazo y si el plazo venció; sin claridad sobre el mandato no hay reclamo sólido.",
   "Conviene requerir el cumplimiento por escrito, con referencia a la decisión, el plazo y la consecuencia contractual que se invocaría, sin amenazas infundadas.",
   "Las vías ante un incumplimiento dependen de la normativa vigente y el contrato: pueden incluir requerimientos formales, acciones ante la Junta o el inicio de mecanismos posteriores.",
   "La obra no debe paralizarse por decisión unilateral si el contrato y la norma no lo permiten; verificar antes cualquier medida.",
   "El cuaderno de obra debe registrar los hechos vinculados con el incumplimiento y sus efectos en plazo y costo.",
   "Mantener la comunicación abierta con la contraparte puede resolver el problema; muchas veces se trata de trabas administrativas, no de negativa.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Confirmar el contenido exacto de la decisión y el vencimiento del plazo de cumplimiento.",
   "Reunir evidencia del incumplimiento: cartas, asientos, registros y comunicaciones.",
   "Enviar un requerimiento formal con referencia a la decisión, el plazo y lo solicitado.",
   "Registrar en el cuaderno de obra los efectos concretos del incumplimiento.",
   "Consultar con el área legal las vías disponibles según el contrato y la norma.",
   "Documentar cada gestión y evaluar una reunión de coordinación antes de escalar."
  ],
  errores: [
   "Reclamar sin sustento documental: acompañar la decisión y las pruebas.",
   "Paralizar sin base contractual: verificar los requisitos antes de cualquier medida.",
   "Dejar pasar el tiempo sin requerir: enviar el requerimiento oportuno.",
   "Cerrar el diálogo: intentar coordinar cuando sea razonable."
  ],
  ejemplo: "La Junta ordenó a la entidad tramitar el pago de un adicional en un plazo determinado (monto ilustrativo: S/ 430 mil). Vencido el plazo, el contratista revisa la decisión, envía una carta de requerimiento con la evidencia y registra en el cuaderno de obra la afectación a su flujo de caja. La entidad responde que hubo un retraso en un trámite presupuestal y propone una fecha de pago. El contratista evalúa la propuesta con su asesor y, de no cumplirse, considera las vías previstas. Datos ilustrativos; el resultado depende de las normas y el contrato.",
  practica: "Redacta una carta de requerimiento de cumplimiento de cinco líneas para un caso ficticio: cita la decisión, el plazo vencido, lo solicitado y una nueva fecha razonable, sin amenazas.",
  quiz: [
   {q:"¿Qué es lo primero ante un posible incumplimiento?", o:["Paralizar la obra","Confirmar qué se ordenó y si el plazo venció","Publicar el caso","Renunciar al contrato"], ok:1, why:"Sin claridad sobre el mandato y el plazo no hay reclamo sólido."},
   {q:"¿Por qué documentar los efectos del incumplimiento?", o:["Para llenar el expediente","Para evitar pagar","Para retrasar el cronograma","Porque sustentan futuras acciones sobre plazo y costo"], ok:3, why:"El registro permite acreditar el impacto en plazo y costo si se acude a otras vías."}
  ]
 },
 "10.1": {
  resumen: "Un sustento técnico defendible es ordenado, trazable y consistente con el contrato. No se trata de acumular documentos, sino de contar una historia técnica verificable donde cada afirmación tiene su respaldo.",
  ideas: [
   "Todo sustento debe partir del contrato de obra, el expediente técnico aprobado y las modificaciones formalmente aprobadas; lo que no consta ahí requiere justificación adicional.",
   "La trazabilidad significa que cada dato pueda rastrearse a su fuente: plano, metrado, asiento del cuaderno, ensayo o valorización.",
   "La consistencia entre documentos es esencial: cifras distintas para un mismo concepto en dos escritos debilitan la credibilidad.",
   "Un buen sustento distingue entre hechos, cálculos y opiniones; los hechos se prueban, los cálculos se explican y las opiniones se fundamentan.",
   "La cronología debe ser clara: qué pasó, cuándo se comunicó, qué se respondió y con qué efecto en plazo y costo.",
   "Un formato estándar de presentación, con índice, numeración de anexos y resumen ejecutivo, facilita la lectura de la Junta.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Definir con claridad la pregunta técnica que se quiere probar.",
   "Reunir los documentos base: contrato, expediente técnico, cronograma, cuaderno de obra y valorizaciones.",
   "Construir una cronología de hechos con su fuente.",
   "Preparar cálculos con hojas verificables y supuestos explícitos.",
   "Revisar la consistencia de cifras y fechas entre todos los documentos.",
   "Armar el sustento con índice, resumen y anexos numerados."
  ],
  errores: [
   "Presentar anexos sin explicar su relevancia: indicar qué prueba cada anexo.",
   "Cifras inconsistentes entre escritos: unificar en una sola hoja de control.",
   "Omitir supuestos de cálculo: hacerlos explícitos.",
   "Sustentar con opiniones sin datos: respaldar con documentos y mediciones."
  ],
  ejemplo: "Un contratista sostiene que un frente de trabajo estuvo bloqueado durante varias semanas (plazo ilustrativo). Para armar un sustento defendible, construye una cronología con asientos del cuaderno de obra, cartas enviadas y fotografías fechadas. Prepara una hoja que relaciona las partidas afectadas con el cronograma vigente y un resumen ejecutivo de una página. La entidad puede tener otra lectura; por eso el contratista señala qué documentos respaldan cada afirmación. No se garantiza un resultado. Datos ilustrativos.",
  practica: "Elige una supuesta controversia de obra y arma un índice de sustento técnico de diez ítems, indicando para cada uno la fuente documental y qué afirmación respalda.",
  quiz: [
   {q:"¿Qué significa trazabilidad en un sustento técnico?", o:["Que cada dato pueda rastrearse a su fuente documental","Que el informe sea largo","Que tenga muchas fotos","Que lo firme un gerente"], ok:0, why:"La trazabilidad permite verificar cada dato en su origen y da credibilidad."},
   {q:"¿Qué debilita la credibilidad de un sustento?", o:["Un índice claro","Anexos numerados","Cifras inconsistentes entre documentos","Un resumen ejecutivo"], ok:2, why:"Las contradicciones entre escritos restan confianza en toda la exposición."}
  ]
 },
 "10.2": {
  resumen: "Probar un adicional exige demostrar que el trabajo no estaba en el expediente técnico aprobado, que era necesario y que su costo es razonable. Los metrados, los planos y el cuaderno de obra son la base de esa demostración.",
  ideas: [
   "Lo primero es comparar el trabajo ejecutado o requerido con el expediente técnico aprobado: planos, especificaciones, metrados y presupuesto. Si estaba previsto, no es adicional.",
   "El sustento debe explicar la necesidad: por qué el trabajo es indispensable para la finalidad de la obra y qué ocurriría sin él.",
   "Los metrados se sustentan con planos, croquis y hojas de cálculo; conviene que sean verificables por la supervisión.",
   "Los precios se analizan con los precios unitarios del contrato cuando existan, y con análisis de costos justificados cuando se trate de partidas nuevas, según lo permita la normativa.",
   "El procedimiento de aprobación de adicionales lo fijan la ley, su reglamento y el contrato; hay que verificar autorizaciones y plazos antes de ejecutar.",
   "El cuaderno de obra debe registrar la detección de la necesidad y las comunicaciones cursadas.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Comparar el trabajo con el expediente técnico aprobado y documentar la diferencia.",
   "Registrar en el cuaderno de obra la necesidad y comunicarla formalmente.",
   "Elaborar planos o croquis y hojas de metrado del trabajo adicional.",
   "Preparar el presupuesto con precios unitarios contractuales o análisis de costos justificados.",
   "Contrastar el sustento con la supervisión antes de presentarlo.",
   "Verificar en la norma vigente los requisitos de aprobación y presentar el expediente."
  ],
  errores: [
   "Ejecutar antes de contar con la aprobación exigida: verificar requisitos previos.",
   "Comparar con un expediente desactualizado: usar la versión aprobada vigente.",
   "Metrados sin respaldo gráfico: incluir planos, croquis y cálculos.",
   "No registrar la necesidad en el cuaderno: anotar el hecho al detectarlo."
  ],
  ejemplo: "Durante excavaciones en una obra de saneamiento (monto ilustrativo: S/ 7 millones) se encuentra un suelo distinto al del estudio de suelos, que exige un mejoramiento no previsto. El residente anota el hallazgo, la supervisión lo verifica y se elabora un sustento: comparación con el expediente técnico, metrado del mejoramiento con croquis, análisis de costos y fotografías fechadas. La entidad evaluará si corresponde y cómo se aprueba según la normativa. No se asegura que se apruebe. Datos ilustrativos.",
  practica: "Elabora una lista de verificación de diez ítems para probar un adicional: comparación con el expediente, necesidad, metrados, precios, registro en cuaderno y aprobaciones a verificar.",
  quiz: [
   {q:"¿Qué se debe comparar primero al plantear un adicional?", o:["El precio del cemento","El trabajo con el expediente técnico aprobado","El perfil del supervisor","El nombre de la obra"], ok:1, why:"Si el trabajo estaba previsto en el expediente, no sería adicional."},
   {q:"¿Qué respalda mejor un metrado?", o:["Un comentario verbal","Una estimación sin cálculos","Una foto sola","Planos o croquis con hoja de cálculo verificable"], ok:3, why:"El metrado debe poder verificarse por terceros con base gráfica y cálculo."}
  ]
 },
 "10.3": {
  resumen: "Una ampliación de plazo se prueba mostrando que un evento afectó la ruta crítica y retrasó la terminación de la obra. Sin un cronograma vigente y un análisis coherente, es difícil demostrar el efecto real del evento sobre el plazo contractual.",
  ideas: [
   "El punto de partida es el cronograma vigente aprobado: allí se identifica la ruta crítica, es decir, la secuencia de actividades que determina la fecha de terminación.",
   "Un evento solo justifica ampliación si afecta actividades críticas o convierte en críticas otras actividades; retrasos en tareas con holgura pueden no alterar la fecha final.",
   "Las causales y el procedimiento de solicitud los establecen la Ley de Contrataciones Públicas y su Reglamento vigentes y el contrato; los plazos para solicitar deben verificarse cuidadosamente.",
   "El cuaderno de obra debe registrar el inicio y el fin de la circunstancia que afecta el plazo, con asientos oportunos del residente y del supervisor.",
   "El análisis debe mostrar el cronograma antes del evento, el cronograma con el evento y la diferencia en la fecha de término.",
   "Separar retrasos atribuibles a cada parte y eventos concurrentes evita reclamar más de lo que corresponde.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Obtener el cronograma vigente y confirmar su ruta crítica.",
   "Identificar el evento y las actividades que afecta, con su fecha de inicio y fin.",
   "Registrar y comunicar el evento en el cuaderno de obra y por carta, en los plazos aplicables.",
   "Modelar el cronograma con y sin el evento para medir el efecto en la fecha final.",
   "Separar demoras propias, de la contraparte y concurrentes.",
   "Presentar la solicitud con el análisis, el cronograma actualizado y los anexos."
  ],
  errores: [
   "Solicitar tarde: controlar los plazos desde el inicio del evento.",
   "Basarse en un cronograma no aprobado o desactualizado: usar el vigente.",
   "Ignorar la holgura: si la actividad no era crítica, explicar por qué igual afectó la fecha final.",
   "Reclamar sin separar concurrencias: distinguir la responsabilidad de cada parte."
  ],
  ejemplo: "En una obra de edificación (plazo ilustrativo de 240 días), una entrega parcial del terreno impide iniciar la cimentación de un bloque. El planificador revisa la ruta crítica y comprueba que esa actividad estaba en ella. Modela el cronograma con la fecha real de entrega y obtiene una diferencia en la terminación. Junto con los asientos del cuaderno y las cartas cursadas, presenta la solicitud. La entidad podría tener otra lectura del cronograma. No se garantiza el reconocimiento. Datos ilustrativos.",
  practica: "Dibuja una red simple de seis actividades, identifica la ruta crítica y simula un retraso en una actividad crítica y otro en una con holgura. Explica cuál afecta la fecha final.",
  quiz: [
   {q:"¿Qué debe afectar un evento para justificar ampliación de plazo?", o:["Cualquier actividad","Solo la ruta crítica o actividades que la vuelvan crítica","Solo la contabilidad","El cuaderno de obra"], ok:1, why:"Si el evento no altera la fecha final, no hay efecto en el plazo contractual."},
   {q:"¿Por qué el cuaderno de obra es relevante en una ampliación?", o:["Reemplaza el cronograma","Fija el precio","Lo exige solo el supervisor","Registra el inicio y fin del evento con oportunidad"], ok:3, why:"Los asientos oportunos dan prueba contemporánea del evento y su duración."}
  ]
 },
 "10.4": {
  resumen: "Los mayores gastos generales compensan costos indirectos adicionales por un mayor plazo reconocido o por una paralización imputable a la contraparte. Su sustento requiere demostrar el plazo, la composición de los gastos y el vínculo causal.",
  ideas: [
   "Los gastos generales son costos de dirección y soporte de la obra que no se asocian a una partida específica: personal, oficina, seguros, servicios, entre otros.",
   "Su reconocimiento y cálculo dependen de la Ley de Contrataciones Públicas y su Reglamento vigentes y del contrato; debe verificarse cuándo proceden y cómo se calculan.",
   "El sustento parte del presupuesto de gastos generales del contrato y de la relación con el plazo reconocido o el periodo afectado.",
   "Hay que demostrar que el mayor plazo o la paralización generó costos reales o proporcionales según lo que establezca la norma y el contrato.",
   "El cálculo debe ser transparente: cuadro con rubros, montos, periodo y criterio de proporcionalidad, evitando duplicar conceptos ya pagados.",
   "Los documentos contables y de planilla, contratos de alquiler y seguros respaldan los importes reclamados.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Confirmar que exista un plazo reconocido o un periodo de paralización imputable a la contraparte.",
   "Obtener el desagregado de gastos generales del presupuesto contractual.",
   "Definir el método de cálculo con base en el contrato y la norma vigente.",
   "Reunir evidencias de los costos: planillas, facturas, contratos, seguros.",
   "Elaborar un cuadro por rubro y periodo, separando lo ya reconocido.",
   "Presentar el cálculo con hojas verificables y la relación causal explicada."
  ],
  errores: [
   "Reclamar sin plazo reconocido: primero sustentar el evento y su efecto.",
   "Duplicar conceptos ya incluidos en valorizaciones: revisar lo pagado.",
   "Utilizar cifras estimadas sin respaldo: incorporar documentos contables.",
   "Mezclar gastos generales con costos directos: clasificar cada rubro."
  ],
  ejemplo: "Tras una ampliación reconocida de 30 días (dato ilustrativo) en una obra vial de S/ 10 millones (ilustrativo), el contratista prepara el sustento de mayores gastos generales. Parte del desagregado del presupuesto, calcula el gasto diario proporcional según el criterio que fija el contrato y la norma, y lo contrasta con planillas y alquileres. La entidad revisa si hay duplicidad con valorizaciones anteriores. No se asegura la aceptación de todos los importes. Cifras ilustrativas.",
  practica: "Con un desagregado ficticio de gastos generales de cinco rubros, arma un cuadro para un periodo de 20 días indicando la evidencia documental por rubro y qué criterio de cálculo debes verificar en el contrato.",
  quiz: [
   {q:"¿Qué se necesita antes de calcular mayores gastos generales?", o:["Un plazo reconocido o periodo de paralización imputable a la contraparte","Un nuevo contrato","Cambiar al residente","Un informe de marketing"], ok:0, why:"Los mayores gastos se vinculan a un mayor plazo o paralización con causa reconocida."},
   {q:"¿Qué riesgo debe evitarse al calcularlos?", o:["Usar hojas de cálculo","Presentar anexos","Duplicar conceptos ya pagados","Registrar en cuaderno"], ok:2, why:"Reclamar lo ya incluido en valorizaciones resta credibilidad y puede ser observado."}
  ]
 },
 "10.5": {
  resumen: "El reajuste de precios compensa las variaciones de costos durante la obra mediante fórmulas polinómicas. Entender su lógica permite verificar cálculos, detectar errores de índices y sustentar diferencias con claridad.",
  ideas: [
   "La fórmula polinómica expresa el costo de la obra como una combinación de componentes como mano de obra, materiales, equipos y otros, cada uno con su coeficiente y su índice.",
   "Los índices unificados de precios los publica la entidad competente; hay que verificar en la norma vigente cuáles corresponden, su periodicidad y la fecha base aplicable.",
   "El reajuste se calcula comparando índices del periodo de valorización con los de la fecha base, según lo que establezcan el contrato y la normativa.",
   "Los errores frecuentes surgen por usar un índice equivocado, un mes distinto al que corresponde o coeficientes que no coinciden con la fórmula del contrato.",
   "Los montos por reajuste deben aplicarse sobre la base de cálculo que fija el contrato, sin duplicar con otros conceptos.",
   "Documentar cada cálculo en una hoja que muestre índices, fechas, coeficientes y resultados facilita su revisión por la supervisión.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Ubicar la fórmula polinómica del contrato y sus coeficientes.",
   "Confirmar la fecha base y los índices aplicables según la normativa.",
   "Tomar los índices del periodo de cada valorización y organizarlos en una hoja.",
   "Calcular el factor de reajuste con la fórmula y aplicarlo a la base contractual.",
   "Contrastar el resultado con la supervisión y la entidad.",
   "Archivar el cálculo con las fuentes de índices para futuras revisiones."
  ],
  errores: [
   "Usar índices de un mes incorrecto: verificar la fecha de referencia.",
   "Cambiar coeficientes sin respaldo: usar exactamente los del contrato.",
   "Aplicar el reajuste sobre una base inadecuada: revisar lo que dispone el contrato.",
   "No conservar las fuentes de los índices: guardar copias de las publicaciones."
  ],
  ejemplo: "En una obra de S/ 18 millones (monto ilustrativo), el supervisor revisa el cálculo de reajuste de una valorización. Descubre que el contratista usó el índice de un mes distinto al correspondiente. Al recalcular con el índice del periodo indicado por la norma vigente y la fórmula del contrato, el factor cambia levemente. Ambas partes acuerdan corregir y dejan la hoja de cálculo con las fuentes. El ejemplo no anticipa cifras reales; solo ilustra la verificación.",
  practica: "Construye una hoja simple con una fórmula polinómica de cuatro componentes, coeficientes ficticios e índices de dos fechas, y calcula el factor de reajuste. Indica qué datos reales deberías verificar en el contrato.",
  quiz: [
   {q:"¿Qué conforma una fórmula polinómica?", o:["Componentes con coeficientes e índices de precios","Una lista de proveedores","El cronograma","Solo el precio total"], ok:0, why:"Combina coeficientes de los insumos con sus índices para ajustar el precio."},
   {q:"¿Cuál es un error común en reajustes?", o:["Guardar la hoja de cálculo","Usar un índice de un mes que no corresponde","Verificar con la supervisión","Documentar fuentes"], ok:1, why:"El mes del índice determina el factor, por lo que debe coincidir con el periodo aplicable."}
  ]
 },
 "10.6": {
  resumen: "Los metrados y las valorizaciones son la evidencia cotidiana del avance de obra. Bien llevados, permiten sustentar pagos, adicionales y reclamos; mal llevados, generan disputas sobre lo que realmente se ejecutó.",
  ideas: [
   "El metrado registra las cantidades ejecutadas por partida; la valorización las multiplica por precios unitarios y suma otros conceptos según el contrato.",
   "Lo ideal es que los metrados se elaboren y verifiquen conjuntamente entre residente y supervisor, con planos y croquis, evitando discrepancias posteriores.",
   "Las valorizaciones deben presentarse y aprobarse en los plazos y con los documentos que establezcan el contrato y la normativa vigente.",
   "Los metrados de partidas que se miden por unidad global o suma alzada requieren criterios claros sobre qué se considera avance.",
   "Las observaciones a una valorización deben ser específicas: partida, cantidad, precio y razón, para poder resolverse rápidamente.",
   "Los metrados de la valorización pueden ser prueba central en una disputa; por eso conviene conservar la versión firmada y sus anexos.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Elaborar los metrados del periodo con planos, croquis y mediciones de campo.",
   "Verificarlos con la supervisión y registrar la conformidad en el cuaderno o en acta.",
   "Preparar la valorización con precios unitarios contractuales y demás conceptos aplicables.",
   "Presentarla dentro del plazo previsto y con los anexos exigidos.",
   "Documentar las observaciones y su respuesta, con partida y cantidad específicas.",
   "Archivar las versiones aprobadas y las hojas de metrado."
  ],
  errores: [
   "Metrados sin verificación conjunta: coordinar mediciones con la supervisión.",
   "Observaciones genéricas: precisar partida, cantidad y razón.",
   "Perder versiones firmadas: mantener un archivo ordenado.",
   "Valorizar partidas sin avance verificable: respaldar con registros."
  ],
  ejemplo: "En una obra de pavimentación (monto ilustrativo: S/ 5 millones) surge una diferencia entre el contratista y el supervisor sobre el metrado de una partida de base granular. El contratista presenta secciones transversales y controles topográficos; el supervisor aporta sus propias mediciones. Programan una medición conjunta, levantan acta con los resultados y ajustan la valorización. La revisión no asegura que todas las diferencias se resuelvan, pero deja evidencia útil si la controversia persiste. Datos ilustrativos.",
  practica: "Prepara una planilla de metrado para tres partidas ficticias con cantidad, fuente (plano, croquis, medición) y conformidad de la supervisión. Señala qué documentos guardarías para una eventual disputa.",
  quiz: [
   {q:"¿Qué facilita evitar disputas sobre metrados?", o:["No revisar las cantidades","Medir solo al final de la obra","Verificar en conjunto con la supervisión y dejar registro","Ocultar planos"], ok:2, why:"La verificación conjunta y el registro reducen discrepancias posteriores."},
   {q:"¿Cómo deben formularse las observaciones a una valorización?", o:["De forma genérica","Con partida, cantidad, precio y razón específicos","Verbalmente","Sin fecha"], ok:1, why:"La precisión permite resolver el punto rápidamente y sirve de prueba."}
  ]
 },
 "10.7": {
  resumen: "El registro fotográfico, topográfico y de ensayos aporta evidencia objetiva del estado y avance de la obra. Para que sea útil como prueba debe ser fechado, ubicado, trazable y coherente con el resto del expediente.",
  ideas: [
   "Las fotografías sirven cuando muestran fecha, lugar y referencia de escala; una imagen sin contexto difícilmente prueba algo por sí sola.",
   "Conviene establecer puntos fijos de toma y una periodicidad, de modo que se pueda comparar la evolución de un frente en el tiempo.",
   "Los levantamientos topográficos deben indicar equipo, control horizontal y vertical, fecha y responsable, y ser contrastables con los planos del expediente técnico.",
   "Los ensayos de laboratorio requieren identificar la muestra, el lugar de extracción, la norma técnica aplicada, el laboratorio y la fecha, cuando corresponda.",
   "Cada registro debe vincularse con un asiento del cuaderno de obra o un informe, para integrarlo a la cronología de hechos.",
   "Los archivos digitales deben conservarse en su formato original con metadatos, y con respaldo, para evitar cuestionamientos de manipulación.",
   "Verificar la norma vigente y el expediente técnico aprobado."
  ],
  pasos: [
   "Definir un protocolo de registro: puntos de toma, periodicidad y responsables.",
   "Tomar fotografías con fecha, referencia de escala y descripción breve.",
   "Programar levantamientos topográficos en hitos relevantes y firmar los planos resultantes.",
   "Gestionar ensayos con laboratorios idóneos y documentar la cadena de custodia.",
   "Vincular cada registro con asientos del cuaderno o informes de la supervisión.",
   "Archivar los originales con respaldo y un índice de consulta."
  ],
  errores: [
   "Fotos sin fecha ni ubicación: incluir referencias y descripciones.",
   "Topografía sin control verificable: documentar equipo y puntos de control.",
   "Ensayos sin trazabilidad: registrar muestra, norma, laboratorio y fecha.",
   "Editar o renombrar archivos originales: conservar copias intactas."
  ],
  ejemplo: "En una obra de defensa ribereña (monto ilustrativo: S/ 14 millones), el contratista alega que una crecida dañó trabajos ya ejecutados. Presenta fotografías fechadas desde puntos fijos antes y después del evento, un levantamiento topográfico del tramo afectado y ensayos de resistencia de las estructuras cercanas, cada uno vinculado a asientos del cuaderno de obra. La contraparte revisa la trazabilidad de los archivos y solicita las mediciones originales. La Junta valorará todo en conjunto. Datos ilustrativos.",
  practica: "Diseña un protocolo de registro de una semana para una obra ficticia: cinco puntos fotográficos, un levantamiento topográfico y un ensayo, indicando responsable, formato y el asiento de cuaderno con el que se vincula.",
  quiz: [
   {q:"¿Qué hace más útil una fotografía como prueba?", o:["Que sea bonita","Que tenga fecha, ubicación, escala y descripción","Que sea muy grande","Que tenga filtros"], ok:1, why:"El contexto permite situar la imagen en el tiempo y el espacio."},
   {q:"¿Qué se debe conservar de los archivos digitales?", o:["Solo capturas de pantalla","Solo impresiones","Solo resúmenes","Los originales con metadatos y respaldo"], ok:3, why:"Los originales con metadatos evitan cuestionamientos de manipulación."}
  ]
 }
});
